mapper.insert:
insert into api_access_log (
    method, path, status_code, duration_ms, user_id, username, ip_address, user_agent
) values (
    #{method}, #{path}, #{statusCode}, #{durationMs}, #{userId}, #{username}, #{ipAddress}, #{userAgent}
)

insert into operation_log (
    user_id, username, method, path, action, status_code, duration_ms, ip_address
) values (
    #{userId}, #{username}, #{method}, #{path}, #{action}, #{statusCode}, #{durationMs}, #{ipAddress}
)
